begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api,cuevo_worker;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table thinking_fixture(course uuid,unit uuid,lesson uuid,activity uuid,assessment uuid,completion uuid,submission uuid,original jsonb,draft jsonb,approved jsonb,xp bigint,results bigint,states bigint);grant select,insert,update on thinking_fixture to cuevo_api;
insert into thinking_fixture(course,unit,lesson,activity,assessment,xp,results,states)values('99610000-0000-4000-8000-000000000001','99620000-0000-4000-8000-000000000001','99630000-0000-4000-8000-000000000001','99640000-0000-4000-8000-000000000001','99650000-0000-4000-8000-000000000001',(select count(*)from app.xp_ledger),(select count(*)from app.result_revisions)+(select count(*)from app.rubric_result_revisions),(select count(*)from app.learner_state_snapshots));
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001',(select course from thinking_fixture),'30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Thinking focus course','Synthetic original task','PUBLISHED');
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001',(select unit from thinking_fixture),(select course from thinking_fixture),'Thinking unit',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001',(select lesson from thinking_fixture),(select unit from thinking_fixture),'Thinking lesson',1,'Read the example.');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)values('10000000-0000-4000-8000-000000000001',(select activity from thinking_fixture),(select lesson from thinking_fixture),'Apply a procedure','practice','Use the example to solve a new problem.',1);
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,status,assignment_state)values('10000000-0000-4000-8000-000000000001',(select assessment from thinking_fixture),(select course from thinking_fixture),'20000000-0000-4000-8000-000000000004','Prepared thinking task','Use and explain the procedure.',10,'DRAFT','CLOSED');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update thinking_fixture set original=internal.read_thinking_focus('activity',activity,null);
select is((select original->>'status'from thinking_fixture),'UNCLASSIFIED','legacy task remains unclassified');
select is(internal.read_thinking_focus_set(jsonb_build_array(jsonb_build_object('kind','activity','id',(select activity from thinking_fixture),'criterionKey',null)))->0->'classification','null'::jsonb,'unclassified page metadata has exact authorized absence receipt');
select throws_ok($$select internal.read_thinking_focus('criterion',(select assessment from thinking_fixture),'missing')$$,'42501',null,'unknown criterion does not invent a source');
select throws_ok($$select internal.read_thinking_focus_set(jsonb_build_array(jsonb_build_object('kind','activity','id',(select activity from thinking_fixture),'criterionKey',null),jsonb_build_object('kind','activity','id',(select activity from thinking_fixture),'criterionKey',null)))$$,'22023',null,'duplicate task source tuples rejected');
update thinking_fixture set draft=internal.thinking_focus_command('draft','activity',activity,null,jsonb_build_object('expectedRevision',0,'expectedSourceVersion',original->>'sourceVersion','focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','APPLY','additionalProcesses',jsonb_build_array('UNDERSTAND')),'rationale','Use a learned procedure in a new example.'),'thinking-draft-key',repeat('a',64),'thinking-test');
select is((select draft->>'status'from thinking_fixture),'AWAITING_REVIEW','author creates a private reviewable task classification');
select is((select draft->>'id'from thinking_fixture),(select draft->'classification'->>'id'from thinking_fixture),'command receipt confirms classification identity');
select throws_ok($$select internal.thinking_focus_command('review','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'decision','APPROVE','reason','Self approval','confirmReview',true),'thinking-self-key',repeat('b',64),'thinking-test')$$,'42501',null,'teacher cannot review');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'status','UNCLASSIFIED','learner cannot see pending classification');
select throws_ok($$select internal.read_thinking_focus_history('activity',(select activity from thinking_fixture),null,25,null)$$,'42501',null,'learner cannot enumerate draft or rejected history');
select throws_ok($$select internal.thinking_focus_command('draft','activity',(select activity from thinking_fixture),null,(select draft from thinking_fixture),'thinking-learner-key',repeat('b',64),'thinking-test')$$,'42501',null,'learner cannot author task demand');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
update thinking_fixture set approved=internal.thinking_focus_command('review','activity',activity,null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',original->>'sourceVersion','decision','APPROVE','reason','Reviewed actual instructions and rationale.','confirmReview',true),'thinking-approve-key',repeat('c',64),'thinking-test');
select is((select approved->>'status'from thinking_fixture),'APPROVED','different coordinator explicitly approves exact source');
select is((select approved->'classification'->>'authorId'from thinking_fixture),'20000000-0000-4000-8000-000000000004','review preserves exact draft author');
select is((select approved->'classification'->>'reviewerId'from thinking_fixture),'20000000-0000-4000-8000-000000000002','review keeps independent reviewer identity');
select is(internal.read_thinking_focus_set(jsonb_build_array(jsonb_build_object('kind','activity','id',(select activity from thinking_fixture),'criterionKey',null)))->0->'source'->>'instructions','','page metadata avoids copying task instructions');
select is(internal.read_thinking_focus_set(jsonb_build_array(jsonb_build_object('kind','activity','id',(select activity from thinking_fixture),'criterionKey',null)))->0->>'sourceVersion',(select approved->>'sourceVersion'from thinking_fixture),'compact metadata preserves exact reviewed source digest');
select lives_ok($$select internal.thinking_focus_command('review','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'decision','APPROVE','reason','Reviewed actual instructions and rationale.','confirmReview',true),'thinking-approve-key',repeat('c',64),'thinking-test')$$,'original review key reconciles exact immutable receipt');
select throws_ok($$select internal.thinking_focus_command('review','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'decision','APPROVE','reason','Changed reason','confirmReview',true),'thinking-approve-key',repeat('d',64),'thinking-test')$$,'22023',null,'same key with changed fingerprint rejected');
select is(jsonb_array_length(internal.read_thinking_focus_course((select course from thinking_fixture),1,null)->'items'),1,'course review page is bounded');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'status','APPROVED','learner sees reviewed published task demand');
update thinking_fixture set completion=gen_random_uuid();insert into app.activity_completions(school_id,id,activity_id,learner_id)values('10000000-0000-4000-8000-000000000001',(select completion from thinking_fixture),(select activity from thinking_fixture),'20000000-0000-4000-8000-000000000012');
select is(internal.read_thinking_focus_snapshot('completion',(select completion from thinking_fixture))->'items'->0->'classification'->>'id',(select approved->>'id'from thinking_fixture),'completion freezes exact approved classification');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.learning_content_command('draft','activity',(select activity from thinking_fixture),jsonb_build_object('resource','activity','expectedRevision',1,'title','Changed task','content','Compare two approaches.','kind','practice','assessmentId',null,'reason','Change task demand'),'thinking-content-draft',repeat('d',64),'thinking-test');
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'status','SOURCE_CHANGED','changed instructions invalidate current staff classification');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->'source'->>'contentRevision','2','reviewer direct source retains current draft revision');
select is(internal.read_thinking_focus_set(jsonb_build_array(jsonb_build_object('kind','activity','id',(select activity from thinking_fixture),'criterionKey',null)))->0->'source'->>'contentRevision','1','coordinator page metadata pins the same published content as its course page');
select is(internal.read_thinking_focus_set(jsonb_build_array(jsonb_build_object('kind','activity','id',(select activity from thinking_fixture),'criterionKey',null)))->0->>'status','APPROVED','exact published page retains its reviewed task demand');
select is(internal.read_thinking_focus_set(jsonb_build_array(jsonb_build_object('kind','activity','id',(select activity from thinking_fixture),'criterionKey',null)))->0->>'canReview','false','page projection is separate from direct reviewer command permission');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.thinking_focus_command('draft','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',0,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','APPLY','additionalProcesses',jsonb_build_array('UNDERSTAND')),'rationale','Use a learned procedure in a new example.'),'thinking-draft-key',repeat('a',64),'thinking-test')$$,'22023',null,'original key cannot bypass changed current source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'status','APPROVED','published task keeps reviewed demand while next draft changes');
select is(internal.read_thinking_focus_snapshot('completion',(select completion from thinking_fixture))->'items'->0->'source'->>'instructions','Use the example to solve a new problem.','recorded snapshot never substitutes new draft instructions');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.learning_content_command('publish','activity',(select activity from thinking_fixture),'{"expectedRevision":2,"confirmPublication":true}','thinking-content-publish',repeat('e',64),'thinking-test');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'status','UNCLASSIFIED','changed-content publication cannot inherit review');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.learning_content_command('draft','activity',(select activity from thinking_fixture),'{"resource":"activity","expectedRevision":3,"title":"Reviewed comparison","content":"Compare two approaches.","kind":"practice","assessmentId":null,"reason":"Prepare the exact comparison source"}','thinking-same-content-draft',repeat('4',64),'thinking-test')is not null;
update thinking_fixture set original=internal.read_thinking_focus('activity',activity,null);
select internal.thinking_focus_command('draft','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',2,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','ANALYZE','additionalProcesses','[]'::jsonb),'rationale','Compare the steps used in two approaches.'),'thinking-analysis-draft',repeat('5',64),'thinking-test')is not null;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
update thinking_fixture set draft=internal.thinking_focus_command('review','activity',activity,null,jsonb_build_object('expectedRevision',3,'expectedSourceVersion',original->>'sourceVersion','decision','APPROVE','reason','Reviewed this exact comparison task.','confirmReview',true),'thinking-analysis-review',repeat('6',64),'thinking-test');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.learning_content_command('publish','activity',(select activity from thinking_fixture),'{"expectedRevision":4,"confirmPublication":true}','thinking-same-content-publish',repeat('7',64),'thinking-test')is not null;
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'revision','5','unchanged activity publication appends immutable reviewed lineage');
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->'classification'->>'reviewedAt',(select draft->'classification'->>'reviewedAt'from thinking_fixture),'publication preserves original independent review date');
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->'classification'->>'reviewReason',(select draft->'classification'->>'reviewReason'from thinking_fixture),'publication preserves independent review reason');
select is(jsonb_array_length(internal.read_thinking_focus_history('activity',(select activity from thinking_fixture),null,2,null)->'items'),2,'history returns bounded exact immutable revisions');
select is(internal.read_thinking_focus_history('activity',(select activity from thinking_fixture),null,2,null)->'items'->0->>'status','APPROVED','historical decision remains source-pinned approval');
select throws_ok($$select internal.read_thinking_focus_history('activity',(select activity from thinking_fixture),null,2,'ffffffff-ffff-4fff-8fff-ffffffffffff')$$,'22023',null,'unrelated history cursor denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
update thinking_fixture set original=internal.read_thinking_focus('activity',activity,null);
select internal.thinking_focus_command('draft','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',5,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','EVALUATE','additionalProcesses','[]'::jsonb),'rationale','Admin edits task demand classification.'),'thinking-admin-draft',repeat('8',64),'thinking-test')is not null;
select throws_ok($$select internal.thinking_focus_command('review','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',6,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'decision','APPROVE','reason','Self review','confirmReview',true),'thinking-admin-self',repeat('9',64),'thinking-test')$$,'42501',null,'admin cannot review own edited draft inherited from teacher history');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select internal.thinking_focus_command('review','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',6,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'decision','REJECT','reason','Current demand does not support that classification.','confirmReview',true),'thinking-rejection',repeat('a',64),'thinking-test')is not null;
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'status','REJECTED','review rejection appends immutable decision');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'status','UNCLASSIFIED','rejected exact task metadata remains private to staff');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.learning_content_command('retire','activity',(select activity from thinking_fixture),'{"expectedRevision":5,"reason":"Retain old comparison history","confirmRetirement":true}','thinking-retire',repeat('3',64),'thinking-test')is not null;
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'status','SOURCE_CHANGED','retired task remains source-changed for authorized staff');
select is(internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'canAuthor','false','retired task does not advertise a permitted new draft');
select lives_ok($$select internal.read_thinking_focus_course((select course from thinking_fixture),25,null)$$,'retired mapped task does not break course review queue');
select lives_ok($$select internal.read_thinking_focus_history('activity',(select activity from thinking_fixture),null,25,null)$$,'retired task retains staff review history');
select throws_ok($$select internal.thinking_focus_command('draft','activity',(select activity from thinking_fixture),null,jsonb_build_object('expectedRevision',7,'expectedSourceVersion',internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)->>'sourceVersion','focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','APPLY','additionalProcesses','[]'::jsonb),'rationale','Retired source'),'thinking-retired-write',repeat('4',64),'thinking-test')$$,'22023',null,'retired task rejects new metadata mutation');
select internal.prepare_assessment((select assessment from thinking_fixture),'Reviewed prepared task','Use and explain the procedure.',null,10,'61000000-0000-4000-8000-000000000001',null,1);
update thinking_fixture set original=internal.read_thinking_focus('assessment',assessment,null);
select internal.thinking_focus_command('draft','assessment',(select assessment from thinking_fixture),null,jsonb_build_object('expectedRevision',0,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','APPLY','additionalProcesses','[]'::jsonb),'rationale','Task asks use of a procedure.'),'thinking-assessment-draft',repeat('f',64),'thinking-test');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select internal.thinking_focus_command('review','assessment',(select assessment from thinking_fixture),null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'decision','APPROVE','reason','Reviewed prepared assessment.','confirmReview',true),'thinking-assessment-review',repeat('1',64),'thinking-test');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.publish_prepared_assessment((select assessment from thinking_fixture),2,2,1);
select is(internal.read_thinking_focus('assessment',(select assessment from thinking_fixture),null)->>'status','APPROVED','unchanged assessment publication retains reviewed provenance');
select is(internal.read_thinking_focus('assessment',(select assessment from thinking_fixture),null)->>'revision','3','publication creates new immutable classification lineage');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update thinking_fixture set submission=internal.create_learning_submission(assessment,'My worked procedure.');
select is(jsonb_array_length(internal.read_thinking_focus_snapshot('submission',(select submission from thinking_fixture))->'items'),1,'submission snapshots current approved assessment demand');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
update thinking_fixture set original=internal.read_thinking_focus('assessment',assessment,null);
select internal.thinking_focus_command('review','assessment',(select assessment from thinking_fixture),null,jsonb_build_object('expectedRevision',3,'expectedSourceVersion',(select original->>'sourceVersion'from thinking_fixture),'decision','WITHDRAW','reason','Review requires renewal.','confirmReview',true),'thinking-assessment-withdraw',repeat('2',64),'thinking-test');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_thinking_focus('assessment',(select assessment from thinking_fixture),null)->>'status','UNCLASSIFIED','withdrawal removes current learner presentation');
select is(internal.read_thinking_focus_snapshot('submission',(select submission from thinking_fixture))->'items'->0->>'status','APPROVED','withdrawal never rewrites recorded task snapshot');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_thinking_focus_snapshot('submission',(select submission from thinking_fixture))$$,'42501',null,'parent requires exact native published result authority');
select set_config('app.school_id','10000000-0000-4000-8000-000000000002',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000132',true);
select throws_ok($$select internal.read_thinking_focus('activity',(select activity from thinking_fixture),null)$$,'42501',null,'cross-school object cannot be read');
reset role;
select ok(not has_table_privilege('cuevo_api','app.thinking_focus_revisions','SELECT'),'API cannot enumerate raw classification history');
select ok(not has_table_privilege('authenticated','app.thinking_focus_submission_snapshots','SELECT'),'browser cannot enumerate source snapshots');
select ok(not has_function_privilege('authenticated','internal.read_thinking_focus(text,uuid,text)','EXECUTE'),'browser cannot bypass verified API identity');
select ok(not has_function_privilege('cuevo_worker','internal.thinking_focus_command(text,text,uuid,text,jsonb,text,text,text)','EXECUTE'),'worker cannot author or approve task demand');
select ok(not has_function_privilege('cuevo_api','internal.thinking_focus_projection(uuid,jsonb,boolean)','EXECUTE'),'raw revision projection is not a public API');
select ok(not internal.valid_thinking_focus('{"taxonomyVersion":"revised-bloom-2001-cuevo-v1","primaryProcess":"APPLY","additionalProcesses":["APPLY"]}'),'database rejects primary/additional duplication');
select ok(not internal.valid_thinking_focus('{"taxonomyVersion":"revised-bloom-2001-cuevo-v1","primaryProcess":"APPLY","additionalProcesses":[],"learnerLevel":3}'),'database rejects learner-level extension');
select ok(not internal.valid_thinking_focus('{}'),'database rejects absent vocabulary fields');
select throws_ok($$update app.thinking_focus_revisions set rationale='Overwrite history'where id=(select approved->>'id'from thinking_fixture)::uuid$$,'55000',null,'classification history immutable');
select throws_ok($$truncate app.thinking_focus_submission_snapshots$$,'55000',null,'recorded snapshots cannot be truncated');
select is((select count(*)from app.xp_ledger),(select xp from thinking_fixture),'thinking metadata never awards XP');
select is((select count(*)from app.result_revisions)+(select count(*)from app.rubric_result_revisions),(select results from thinking_fixture),'thinking metadata never writes grades');
select is((select count(*)from app.learner_state_snapshots),(select states from thinking_fixture),'thinking metadata never updates learner state');
select ok(exists(select 1 from internal.audit_events where action='thinking_focus.review'and entity_id=(select approved->>'id'from thinking_fixture)::uuid),'review audit committed with source');
select ok(exists(select 1 from internal.outbox_events where type='thinking_focus.reviewed'and entity_id=(select approved->>'id'from thinking_fixture)::uuid),'review durable event committed with source');
create temporary table thinking_worker as select e.id,e.actor_id,e.version,e.metadata,gen_random_uuid()as token from internal.outbox_events e where e.type='thinking_focus.reviewed'and e.entity_id=(select approved->>'id'from thinking_fixture)::uuid;
grant select on thinking_worker to cuevo_worker;
update internal.outbox_events set state='PROCESSING',lease_token=(select token from thinking_worker),lease_until=clock_timestamp()+interval '30 seconds',actor_id='20000000-0000-4000-8000-000000000001'where id=(select id from thinking_worker);
select ok(not internal.thinking_focus_event_source_allowed((select id from thinking_worker)),'event acknowledgement rejects another revision creator');
set local role cuevo_worker;
select throws_ok($$select internal.process_learner_event((select id from thinking_worker),(select token from thinking_worker))$$,'22023',null,'restricted worker denies forged event actor');
reset role;
update internal.outbox_events set actor_id=(select actor_id from thinking_worker),version=(select version+1 from thinking_worker)where id=(select id from thinking_worker);
select ok(not internal.thinking_focus_event_source_allowed((select id from thinking_worker)),'event acknowledgement rejects another immutable revision');
update internal.outbox_events set version=(select version from thinking_worker),metadata=jsonb_set(metadata,'{sourceVersion}','"changed source"')where id=(select id from thinking_worker);
select ok(not internal.thinking_focus_event_source_allowed((select id from thinking_worker)),'event acknowledgement rejects changed source provenance');
update internal.outbox_events set metadata=(select metadata from thinking_worker),lease_until=clock_timestamp()-interval '1 second'where id=(select id from thinking_worker);
set local role cuevo_worker;
select throws_ok($$select internal.process_learner_event((select id from thinking_worker),(select token from thinking_worker))$$,'22023',null,'restricted worker denies expired acknowledgement lease');
reset role;
update internal.outbox_events set lease_until=clock_timestamp()+interval '30 seconds'where id=(select id from thinking_worker);
set local role cuevo_worker;
select throws_ok($$select internal.process_learner_event((select id from thinking_worker),gen_random_uuid())$$,'22023',null,'restricted worker denies another acknowledgement lease token');
select is(internal.process_learner_event((select id from thinking_worker),(select token from thinking_worker))->>'status','ACKNOWLEDGED','restricted worker acknowledges exact event actor and source');
select throws_ok($$select internal.process_learner_event((select id from thinking_worker),(select token from thinking_worker))$$,'22023',null,'completed event cannot acknowledge twice');
reset role;
select is((select count(*)from app.xp_ledger),(select xp from thinking_fixture),'acknowledged thinking event never awards XP');
select is((select count(*)from app.learner_state_snapshots),(select states from thinking_fixture),'acknowledged thinking event never updates attainment');
select*from finish();rollback;
